// 18-tap direct-form FIR, 8-bit samples, PIPELINED: products registered in
// stage 1, summed in stage 2 -> shorter register-to-register path, higher Fmax.
// Functionally identicalto the reference up to a fixed extra latency.
module firr18_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:17];
    reg  [15:0] p  [0:17];
    integer     i;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 18; i = i + 1) begin xs[i] <= 8'd0; p[i] <= 16'd0; end
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 18; i = i + 1) xs[i] <= xs[i-1];
            p[0] <= 8'd2 * x + 8'd3;
            p[1] <= 8'd4 * xs[0] + 8'd7;
            p[2] <= 8'd6 * xs[1] + 8'd11;
            p[3] <= 8'd8 * xs[2] + 8'd15;
            p[4] <= 8'd10 * xs[3] + 8'd19;
            p[5] <= 8'd12 * xs[4] + 8'd23;
            p[6] <= 8'd14 * xs[5] + 8'd27;
            p[7] <= 8'd16 * xs[6] + 8'd31;
            p[8] <= 8'd18 * xs[7] + 8'd35;
            p[9] <= 8'd20 * xs[8] + 8'd39;
            p[10] <= 8'd22 * xs[9] + 8'd43;
            p[11] <= 8'd24 * xs[10] + 8'd47;
            p[12] <= 8'd26 * xs[11] + 8'd51;
            p[13] <= 8'd28 * xs[12] + 8'd55;
            p[14] <= 8'd30 * xs[13] + 8'd59;
            p[15] <= 8'd32 * xs[14] + 8'd63;
            p[16] <= 8'd34 * xs[15] + 8'd67;
            p[17] <= 8'd36 * xs[16] + 8'd71;
            y <= p[0] + p[1] + p[2] + p[3] + p[4] + p[5] + p[6] + p[7] + p[8] + p[9] + p[10] + p[11] + p[12] + p[13] + p[14] + p[15] + p[16] + p[17];
        end
    end
endmodule
